script:
/*
 * OKAVANGO FOODS
 * OPERATIONAL PAYMENT REQUEST - FINANCE ACTIONS
 *
 * ERPNext / Frappe v15
 *
 * Client Script DocType:
 * Operational Payment Request
 *
 * Required Finance role:
 * Operational Payment Finance
 *
 * Existing backend methods:
 * 1. get_button_state
 * 2. get_journal_entry_prefill
 *
 * IMPORTANT:
 * - Does not post Journal Entries automatically.
 * - Does not bypass workflow or accounting permissions.
 * - Prevents a second draft from being opened when
 *   the backend reports an existing Journal Entry.
 */

frappe.ui.form.on('Operational Payment Request', {

    refresh: function (frm) {

        // ------------------------------------------
        // 1. CHECK USER PERMISSIONS
        // ------------------------------------------

        const is_finance =
            frappe.user.has_role('Operational Payment Finance') ||
            frappe.session.user === 'Administrator';

        if (!is_finance) {
            return;
        }

        // Do not display on unsaved requests.
        if (frm.is_new()) {
            return;
        }

        // Do not display on cancelled requests.
        if (Number(frm.doc.docstatus) === 2) {
            return;
        }

        // Only approved requests enter Finance processing.
        if (frm.doc.workflow_state !== 'Approved') {
            return;
        }

        const source_name = frm.doc.name;

        const base_method =
            'okavango_enhancements.operational_payment.controls.';

        // ------------------------------------------
        // 2. SHOW FINANCE BUTTON
        // ------------------------------------------

        // No button group: display directly in the
        // form toolbar instead of hiding in Actions.

        frm.add_custom_button(
            __('Create / Open Expense Entry'),
            function () {

                // ----------------------------------
                // 3. VERIFY SUBMITTED STATUS
                // ----------------------------------

                if (Number(frm.doc.docstatus) !== 1) {

                    frappe.msgprint({
                        title: __('Accounting Action Unavailable'),
                        indicator: 'orange',
                        message: __(
                            'This request is Approved but is not ' +
                            'Submitted. The Approved workflow state ' +
                            'must have Document Status 1 before ' +
                            'Finance can create the accounting entry.'
                        )
                    });

                    return;
                }

                // ----------------------------------
                // 4. CHECK FOR EXISTING JOURNAL ENTRY
                // ----------------------------------

                frappe.call({

                    method:
                        base_method + 'get_button_state',

                    args: {
                        source_name: source_name
                    },

                    freeze: true,

                    freeze_message:
                        __('Checking existing accounting entries...'),

                    callback: function (r) {

                        if (r.exc) {
                            return;
                        }

                        if (
                            frm.doc.name !== source_name ||
                            Number(frm.doc.docstatus) !== 1 ||
                            frm.doc.workflow_state !== 'Approved'
                        ) {
                            return;
                        }

                        const state = r.message;

                        if (!state) {

                            frappe.msgprint({
                                title: __('Finance Check Failed'),
                                indicator: 'red',
                                message: __(
                                    'The server did not return an ' +
                                    'accounting status. Check the ' +
                                    'get_button_state backend method.'
                                )
                            });

                            return;
                        }

                        // ----------------------------------
                        // 5. OPEN EXISTING JOURNAL ENTRY
                        // ----------------------------------

                        if (state.existing_name) {

                            frappe.show_alert({
                                message: __(
                                    'Opening existing Journal Entry.'
                                ),
                                indicator: 'blue'
                            });

                            frappe.set_route(
                                'Form',
                                'Journal Entry',
                                state.existing_name
                            );

                            return;
                        }

                        // ----------------------------------
                        // 6. CHECK SERVER AUTHORISATION
                        // ----------------------------------

                        if (!state.allowed) {

                            const reason =
                                state.reason ||
                                state.message ||
                                __(
                                    'The backend has not authorised ' +
                                    'creation of a Journal Entry. ' +
                                    'Check the Finance permissions, ' +
                                    'workflow status and accounting setup.'
                                );

                            frappe.msgprint({
                                title: __('Expense Entry Not Available'),
                                indicator: 'orange',
                                message: $('<div>')
                                    .text(String(reason))
                                    .html()
                            });

                            return;
                        }

                        // ----------------------------------
                        // 7. FETCH JOURNAL ENTRY VALUES
                        // ----------------------------------

                        frappe.call({

                            method:
                                base_method +
                                'get_journal_entry_prefill',

                            args: {
                                source_name: source_name
                            },

                            freeze: true,

                            freeze_message:
                                __('Preparing Expense Journal Entry...'),

                            callback: function (result) {

                                if (result.exc) {
                                    return;
                                }

                                const data = result.message;

                                if (
                                    !data ||
                                    !data.header ||
                                    !Array.isArray(data.accounts) ||
                                    data.accounts.length < 2
                                ) {

                                    frappe.msgprint({
                                        title: __('Invalid Accounting Data'),
                                        indicator: 'red',
                                        message: __(
                                            'The server did not provide ' +
                                            'a complete Journal Entry. ' +
                                            'At least two accounting ' +
                                            'rows are required.'
                                        )
                                    });

                                    return;
                                }

                                const header = data.header;

                                // Check that the backend response
                                // belongs to this payment request.
                                if (
                                    header.custom_operational_payment_request &&
                                    header.custom_operational_payment_request
                                        !== source_name
                                ) {

                                    frappe.msgprint({
                                        title: __('Request Mismatch'),
                                        indicator: 'red',
                                        message: __(
                                            'The returned accounting ' +
                                            'data belongs to another ' +
                                            'payment request.'
                                        )
                                    });

                                    return;
                                }

                                // ----------------------------------
                                // 8. CREATE DRAFT JOURNAL ENTRY
                                // ----------------------------------

                                frappe.new_doc(
                                    'Journal Entry',

                                    {
                                        company: header.company,

                                        voucher_type:
                                            header.voucher_type ||
                                            'Journal Entry',

                                        custom_operational_payment_request:
                                            source_name,

                                        custom_customer_order_reference:
                                            header.custom_customer_order_reference
                                            || ''
                                    },

                                    function (doc) {

                                        doc.posting_date =
                                            header.posting_date ||
                                            frappe.datetime.get_today();

                                        doc.user_remark =
                                            header.user_remark ||
                                            'Operational Payment Request: ' +
                                            source_name;

                                        // Clear any default accounts.
                                        doc.accounts = [];

                                        // Do not copy Frappe row identity
                                        // or parent-document metadata.
                                        const excluded_fields = [
                                            'name',
                                            'doctype',
                                            'parent',
                                            'parentfield',
                                            'parenttype',
                                            'idx',
                                            'docstatus'
                                        ];

                                        data.accounts.forEach(
                                            function (source_row) {

                                                const row =
                                                    frappe.model.add_child(
                                                        doc,
                                                        'accounts'
                                                    );

                                                Object.keys(source_row).forEach(
                                                    function (key) {

                                                        if (
                                                            excluded_fields
                                                                .indexOf(key)
                                                            === -1
                                                        ) {
                                                            row[key] =
                                                                source_row[key];
                                                        }
                                                    }
                                                );
                                            }
                                        );
                                    }
                                );

                                frappe.show_alert({
                                    message: __(
                                        'Journal Entry draft prepared. ' +
                                        'Review, save and submit it.'
                                    ),
                                    indicator: 'green'
                                });
                            },

                            error: function () {

                                frappe.msgprint({
                                    title: __('Accounting Error'),
                                    indicator: 'red',
                                    message: __(
                                        'Unable to prepare the Journal ' +
                                        'Entry. Check the backend method ' +
                                        'and your accounting permissions.'
                                    )
                                });
                            }
                        });
                    },

                    error: function () {

                        frappe.msgprint({
                            title: __('Finance Check Error'),
                            indicator: 'red',
                            message: __(
                                'Unable to check the accounting status. ' +
                                'Verify that get_button_state is installed ' +
                                'and accessible to the Finance role.'
                            )
                        });
                    }
                });
            }
        );
    }
});
